      T(S, 't2', 19.0, 3.1, 'base = 2 → calls still 1 → read → 2', 'cz-mono vux-tiny vux-w', 2, { w: 12.4 });
      lbl(S, 'l2', 19.0, 3.7, ['의존성이 바뀌면 캐시에 표시만 해 두고, 다시 읽을 때 계산해요 · 아무도 안 읽으면 계산도 없어요', 'a dependency change only marks the cache dirty; it recomputes on the next read'], 'w', 2, { w: 12.4 });
      T(S, 't3', 19.0, 5.1, 'parity: 2 → 4 → 6 · downstream runs: 1', 'cz-mono vux-tiny vux-g', 3, { w: 12.4 });
      lbl(S, 'l3', 19.0, 5.7, ['결과가 같으면 뒤의 효과를 깨우지 않아요 · 짝수에서 짝수로 바뀌는 동안 아래쪽은 다시 실행되지 않았어요', 'an unchanged result wakes nothing downstream: even-to-even ran nothing'], 'g', 3, { w: 12.4 });
      lbl(S, 'l4', 19.0, 7.2, ['computed 안에서는 계산만 · 다른 상태를 바꾸거나 요청을 보내는 일은 watch로', 'keep computed pure; changing other state or sending requests belongs in watch'], 'a', 4, { w: 12.4 });
