      lbl(S, 'l2', 19.0, 3.2, ['toRefs는 속성마다 원본을 가리키는 ref를 만들어요 · 꺼낸 뒤에도 5와 6을 따라갔어요', 'toRefs makes a ref per property pointing back at the source: it followed 5 and 6'], 'g', 2, { w: 12.4 });
