      T(S, 't3', 19.0, 5.7, '<h1>Shop</h1> → created once, reused', 'cz-mono vux-tiny vux-a', 3, { w: 12.4 });
      lbl(S, 'l3', 19.0, 6.3, ['바뀌지 않는 h1은 한 번 만든 노드를 캐시해 재사용해요 · 비교 대상에서도 빠져요', 'the static h1 is created once and cached, skipped entirely when diffing'], 'a', 3, { w: 12.4 });
