      lbl(S, 'l2', 19.0, 3.7, ['자식이 props.count를 바꾸려 하자 개발 모드에서 경고가 났고 부모의 값은 1 그대로였어요', 'the child’s attempt to change props.count warned in dev, and the parent kept 1'], 'w', 2, { w: 12.4 });
