      lbl(S, 'l3', 19.0, 5.7, ['하지만 객체 props의 안쪽 속성은 막지 않아요 · 경고 없이 부모의 객체까지 바뀌었어요', 'but inner properties of object props are not blocked: the parent’s object changed silently'], 'r', 3, { w: 12.4 });
