      lbl(S, 'l2', 19.0, 3.7, ['자식은 슬롯을 부를 때 자기 데이터를 넘길 수 있어요 · 부모는 그 item으로 모양을 정해요', 'the child can pass its own data when calling the slot; the parent decides the markup'], 'g', 2, { w: 12.4 });
