      lbl(S, 'l3', 19.0, 6.3, ['부모의 다른 값이 바뀌자 Card는 그대로였고, 슬롯이 읽는 tick이 바뀌자 한 번 다시 그려졌어요', 'an unrelated parent value left Card alone; changing tick, read in the slot, updated it once'], 'g', 3, { w: 12.4 });
