      lbl(S, 'l1', 19.0, 1.7, ['조상이 provide한 값을 자손이 inject로 바로 받아요 · 중간 컴포넌트는 props를 몰라도 돼요', 'an ancestor provides a value that descendants inject directly, skipping the middle'], 'a', 1, { w: 12.4 });
