      lbl(S, 'l2', 19.0, 4.3, ['theme을 dark로 바꾸자 중간 두 컴포넌트는 그대로이고, 값을 쓰는 Leaf만 다시 그려졌어요', 'switching theme to dark left both middle components alone and updated only Leaf'], 'g', 2, { w: 12.4 });
      T(S, 't3', 19.0, 5.7, 'injection "nope" not found → undefined', 'cz-mono vux-tiny vux-w', 3, { w: 12.4 });
      lbl(S, 'l3', 19.0, 6.3, ['provide하지 않은 키를 inject하자 경고와 함께 undefined · 기본값을 두 번째 인자로 줘요', 'injecting an unprovided key warned and gave undefined; pass a default as the 2nd argument'], 'w', 3, { w: 12.4 });
